package com.faijan.interviewhub.service;
import com.faijan.interviewhub.dto.LearningAnalytics;import com.faijan.interviewhub.entity.PracticeAttempt;import com.faijan.interviewhub.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;import java.util.stream.Collectors;
@Service public class AnalyticsService {
 private final PracticeAttemptRepository attempts;private final QuestionBookmarkRepository bookmarks;
 public AnalyticsService(PracticeAttemptRepository a,QuestionBookmarkRepository b){attempts=a;bookmarks=b;}
 @Transactional(readOnly=true) public LearningAnalytics forUser(String email){List<PracticeAttempt> all=attempts.findByUserEmailOrderByStartedAtDesc(email).stream().filter(a->"COMPLETED".equals(a.getStatus())).toList();long examQuestions=all.stream().mapToLong(PracticeAttempt::getTotalQuestions).sum();double avg=all.stream().mapToDouble(this::pct).average().orElse(0),best=all.stream().mapToDouble(this::pct).max().orElse(0);List<LearningAnalytics.TechnologyProgress> tech=all.stream().collect(Collectors.groupingBy(PracticeAttempt::getTechnology,TreeMap::new,Collectors.toList())).entrySet().stream().map(e->{List<PracticeAttempt> rows=e.getValue();return new LearningAnalytics.TechnologyProgress(e.getKey(),rows.size(),rows.stream().mapToLong(PracticeAttempt::getTotalQuestions).sum(),round(rows.stream().mapToDouble(this::pct).average().orElse(0)),round(rows.stream().mapToDouble(this::pct).max().orElse(0)));}).toList();return new LearningAnalytics(all.size(),examQuestions,round(avg),round(best),bookmarks.findByUserEmailOrderByCreatedAtDesc(email).size(),tech);}
 private double pct(PracticeAttempt a){return a.getTotalQuestions()==0?0:a.getScore()*100.0/a.getTotalQuestions();}private double round(double d){return Math.round(d*100.0)/100.0;}
}
